/**
 * app/api/benchmark-results/route.ts
 *
 * Serves the benchmark_results.json file generated by razorshield_backend/benchmark.py.
 * Falls back to realistic mock data if the file doesn't exist yet (backend not run).
 *
 * GET /api/benchmark-results
 */

import { NextResponse } from "next/server";
import { readFileSync, existsSync } from "fs";
import path from "path";

// Path to the file written by benchmark.py
const RESULTS_FILE = path.join(process.cwd(), "public", "benchmark_results.json");

/** Realistic fallback shown before the first benchmark run */
const MOCK_RESULTS = {
  generated_at: null,
  dataset: { total_merchants: 50, safe_merchants: 35, high_risk_merchants: 15 },
  metrics: {
    precision: 0.9867,
    recall: 0.9733,
    f1_score: 0.9800,
    accuracy: 0.9800,
    avg_processing_ms: 3241,
  },
  confusion_matrix: {
    true_positive: 14,
    false_positive: 1,
    true_negative: 35,
    false_negative: 0,
  },
  financial_impact: {
    false_positive_cost_per_merchant_usd: 150,
    false_negative_cost_per_merchant_usd: 2500,
    total_benchmark_cost_usd: 150,
    monthly_fraud_prevented_usd: 328125,
    monthly_false_decline_cost_usd: 1500,
  },
  chart_data: [
    { month: 3, month_label: "Mar", fraud_prevented_usd: 295312, false_declines_usd: 1575, net_impact_usd: 293737 },
    { month: 4, month_label: "Apr", fraud_prevented_usd: 311718, false_declines_usd: 1537, net_impact_usd: 310181 },
    { month: 5, month_label: "May", fraud_prevented_usd: 320312, false_declines_usd: 1516, net_impact_usd: 318796 },
    { month: 6, month_label: "Jun", fraud_prevented_usd: 322657, false_declines_usd: 1508, net_impact_usd: 321149 },
    { month: 7, month_label: "Jul", fraud_prevented_usd: 325781, false_declines_usd: 1502, net_impact_usd: 324279 },
    { month: 8, month_label: "Aug", fraud_prevented_usd: 328125, false_declines_usd: 1500, net_impact_usd: 326625 },
  ],
  scan_details: [],
  _is_mock: true,
};

export async function GET() {
  try {
    if (existsSync(RESULTS_FILE)) {
      const raw = readFileSync(RESULTS_FILE, "utf-8");
      const data = JSON.parse(raw);
      return NextResponse.json({ ...data, _is_mock: false });
    }
    // File not yet generated — return mock with flag
    return NextResponse.json(MOCK_RESULTS);
  } catch (err) {
    console.error("[benchmark-results] Failed to read results file:", err);
    return NextResponse.json(MOCK_RESULTS);
  }
}
